/*
 * The UBL 2.1 structure check: does the document have the shape the OASIS schema gives an invoice or credit note (the elements it allows, in its order,
 * as often as it allows, with values and attributes of the right kind)? The official validators run this schema check before any business rule;
 * the business rules (EN 16931, Peppol …) do not look at the order of the elements, so a document with its elements in the wrong place passes them.
 *
 * The content model is data (ubl-schema-data.js, generated by tests/gen-ubl-schema.py from the OASIS schemas); this file walks the document with it.
 * Its answers are compared with libxml2's XML Schema validation on thousands of documents (tests/xsd-differential.py).
 */
(function () {
  "use strict";
  const S = window.UBL_SCHEMA;
  const PREFIX = {
    "urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2": "cbc:",
    "urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2": "cac:",
    "urn:oasis:names:specification:ubl:schema:xsd:CommonExtensionComponents-2": "ext:"
  };
  const XSI = "http://www.w3.org/2001/XMLSchema-instance", XMLNS = "http://www.w3.org/2000/xmlns/";
  const keyOf = (el) => (el.namespaceURI || "") + "|" + el.localName;
  const nameOfKey = (key) => { const i = key.indexOf("|"); return (PREFIX[key.slice(0, i)] || "") + key.slice(i + 1); };
  const nameOf = (el) => (PREFIX[el.namespaceURI] || "") + el.localName;

  // ---- the lexical forms of the XML Schema types the UBL types are built on
  const TZ = "(?:Z|[+-](?:0\\d|1[0-3]):[0-5]\\d|[+-]14:00)?";
  const DATE = "-?\\d{4,}-\\d\\d-\\d\\d", TIME = "(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?|24:00:00(?:\\.0+)?";
  const realDate = (s) => {
    const m = /^(-?\d{4,})-(\d\d)-(\d\d)/.exec(s);
    if (!m) return false;
    const y = Math.abs(+m[1]), mo = +m[2], d = +m[3];
    if (y === 0 || mo < 1 || mo > 12 || d < 1) return false;    // XML Schema 1.0 has no year 0
    const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    return d <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
  };
  const LEX = {
    decimal: { re: /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/, what: "decimal number" },
    boolean: { re: /^(?:true|false|1|0)$/, what: "true or false" },
    date: { re: new RegExp("^" + DATE + TZ + "$"), ok: realDate, what: "date (YYYY-MM-DD)" },
    time: { re: new RegExp("^(?:" + TIME + ")" + TZ + "$"), what: "time (hh:mm:ss)" },
    dateTime: { re: new RegExp("^" + DATE + "T(?:" + TIME + ")" + TZ + "$"), ok: realDate, what: "date and time" },
    base64Binary: { re: /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/, strip: true, what: "base64 data" },
    language: { re: /^[a-zA-Z]{1,8}(?:-[a-zA-Z0-9]{1,8})*$/, what: "language code" },
    integer: { re: /^[+-]?\d+$/, what: "whole number" },
    positiveInteger: { re: /^\+?0*[1-9]\d*$/, what: "positive whole number" },
    nonNegativeInteger: { re: /^(?:\+?\d+|-0+)$/, what: "whole number, zero or more" }
  };
  // value = the text with the white space the type keeps; returns "" when it fits, else the name of the form it should have
  const lexicalProblem = (base, value) => {
    const L = LEX[base];
    if (!L) return "";    // string, normalizedString, token, anyURI …: any text
    let v = value.replace(/[\t\r\n ]+/g, " ").trim();
    if (L.strip) v = value.replace(/[\t\r\n ]+/g, "");
    return L.re.test(v) && (!L.ok || L.ok(v)) ? "" : L.what;
  };

  // ---- walking the document
  function check(root) {
    const found = [];    // { kind, el, detail }
    const add = (kind, el, detail) => found.push({ kind, el, detail });
    const rootType = S.roots[keyOf(root)];
    if (!rootType) return found;

    function walk(el, tid, path) {
      const T = S.types[tid];
      attributes(el, T);
      const kids = Array.from(el.children);
      if (T.s) {   // a value
        if (kids.length) add("06", el, nameOf(el) + " holds a value only, but contains the element " + nameOf(kids[0]));
        const problem = lexicalProblem(T.s, el.textContent);
        if (problem) add("04", el, nameOf(el) + ": “" + el.textContent.trim().slice(0, 40) + "” does not fit the type: " + problem);
        return;
      }
      // elements only
      for (const n of Array.from(el.childNodes)) if (n.nodeType === 3 && /\S/.test(n.nodeValue)) { add("06", el, nameOf(el) + " contains text, but only elements are allowed"); break; }
      const parts = T.c;
      let i = 0;
      const partOf = [], counts = [];    // for each child: the particle it matched; for each particle: how many it matched
      parts.forEach((p, pi) => {
        let count = 0;
        while (i < kids.length && (p[0] === "*" ? true : keyOf(kids[i]) === p[0]) && (p[2] < 0 || count < p[2])) { partOf[i] = pi; count++; i++; }
        counts[pi] = count;
      });
      const leftover = kids.slice(i);
      // too many of one kind: a run of the same element after its maximum
      leftover.forEach((c, k) => {
        const idx = i + k, key = keyOf(c);
        const pi = parts.findIndex((p) => p[0] === key);
        if (pi < 0) { add("01", c, nameOf(c) + " is not allowed in " + nameOf(el)); return; }
        const p = parts[pi];
        if (p[2] >= 0 && counts[pi] >= p[2] && idx > 0 && keyOf(kids[idx - 1]) === key) add("03", c, nameOf(c) + " occurs more than " + p[2] + (p[2] === 1 ? " time" : " times") + " in " + nameOf(el));
        else {
          const before = kids.slice(0, idx).filter((_, j) => partOf[j] > pi)[0];
          add("01", c, nameOf(c) + " comes in the wrong place in " + nameOf(el) + (before ? ": UBL 2.1 puts it before " + nameOf(before) : ""));
        }
      });
      // required elements that are missing (and not just in the wrong place)
      parts.forEach((p, pi) => {
        if (p[0] !== "*" && counts[pi] < p[1] && !leftover.some((c) => keyOf(c) === p[0])) add("02", el, nameOf(el) + " needs " + nameOfKey(p[0]));
      });
      // below: the children in their places
      kids.forEach((c, j) => {
        if (partOf[j] === undefined) { const t = S.elems[keyOf(c)]; if (t) walk(c, t, path); return; }
        const p = parts[partOf[j]];
        if (p[0] === "*") return;      // extension content: any element, not looked at
        walk(c, S.elems[p[0]], path);
      });
    }

    function attributes(el, T) {
      const allowed = T.a || {};
      for (const a of Array.from(el.attributes)) {
        if (a.namespaceURI === XMLNS || a.namespaceURI === XSI || a.name === "xmlns" || a.name.startsWith("xmlns:")) continue;
        if (a.namespaceURI || !(a.name in allowed)) { add("05", el, nameOf(el) + " has the attribute " + a.name + ", which UBL 2.1 does not allow there"); continue; }
        const problem = lexicalProblem(allowed[a.name][0], a.value);
        if (problem) add("04", el, nameOf(el) + "/@" + a.name + ": “" + a.value.slice(0, 40) + "” does not fit the type: " + problem);
      }
      Object.keys(allowed).forEach((n) => { if (allowed[n][1] && !el.hasAttribute(n)) add("05", el, nameOf(el) + " needs the attribute " + n); });
    }

    // the document element itself is the first particle
    walk(root, rootType, "");
    return found;
  }

  const RULES = [
    ["01", "Every element must be one that UBL 2.1 allows at that place, in the order UBL 2.1 gives (the business rules do not look at the order)"],
    ["02", "Every element that UBL 2.1 requires must be present"],
    ["03", "No element may occur more often than UBL 2.1 allows"],
    ["04", "Every value must have the form of its UBL 2.1 type (number, date, true/false …)"],
    ["05", "Every attribute UBL 2.1 requires must be present, and no other attribute may be used"],
    ["06", "An element holds either a value or other elements, never both"]
  ];
  // reports one result per kind of problem, passing or failing, with the elements that fail
  function report(root, rule) {
    const found = check(root);
    RULES.forEach(([n, text]) => {
      const mine = found.filter((f) => f.kind === n);
      rule("UBL-XSD-" + n, mine.length ? mine.map((f) => f.el) : root, !mine.length, text,
        mine.length ? mine[0].detail : "");
    });
  }
  // Italian: the six rules and the sentences of the details
  if (window.I18N && I18N.addItalian) {
    I18N.addItalian({
      "Every element must be one that UBL 2.1 allows at that place, in the order UBL 2.1 gives (the business rules do not look at the order)": "Ogni elemento deve essere uno di quelli che UBL 2.1 ammette in quel punto, nell'ordine previsto da UBL 2.1 (le regole di business non controllano l'ordine)",
      "Every element that UBL 2.1 requires must be present": "Ogni elemento richiesto da UBL 2.1 deve essere presente",
      "No element may occur more often than UBL 2.1 allows": "Nessun elemento può comparire più spesso di quanto UBL 2.1 consente",
      "Every value must have the form of its UBL 2.1 type (number, date, true/false …)": "Ogni valore deve avere la forma del suo tipo UBL 2.1 (numero, data, vero/falso …)",
      "Every attribute UBL 2.1 requires must be present, and no other attribute may be used": "Ogni attributo richiesto da UBL 2.1 deve essere presente e non si possono usare altri attributi",
      "An element holds either a value or other elements, never both": "Un elemento contiene un valore oppure altri elementi, mai entrambi",
      "decimal number": "numero decimale", "true or false": "vero o falso", "date (YYYY-MM-DD)": "data (AAAA-MM-GG)", "time (hh:mm:ss)": "ora (hh:mm:ss)",
      "date and time": "data e ora", "base64 data": "dati base64", "language code": "codice lingua", "whole number": "numero intero",
      "positive whole number": "numero intero positivo", "whole number, zero or more": "numero intero, zero o più"
    }, [
      ["{a} is not allowed in {b}", "{a} non è ammesso in {b}"],
      ["{a} comes in the wrong place in {b}: UBL 2.1 puts it before {c}", "{a} è nel posto sbagliato in {b}: UBL 2.1 lo mette prima di {c}"],
      ["{a} comes in the wrong place in {b}", "{a} è nel posto sbagliato in {b}"],
      ["{a} occurs more than {n} time in {b}", "{a} compare più di {n} volta in {b}"],
      ["{a} occurs more than {n} times in {b}", "{a} compare più di {n} volte in {b}"],
      ["{a} needs the attribute {b}", "{a} richiede l'attributo {b}"],
      ["{a} needs {b}", "{a} richiede {b}"],
      ["{a} holds a value only, but contains the element {b}", "{a} contiene solo un valore, ma contiene l'elemento {b}"],
      ["{a} contains text, but only elements are allowed", "{a} contiene testo, ma sono ammessi solo elementi"],
      ["{a}: “{v}” does not fit the type: {t}", "{a}: “{v}” non rispetta il tipo: {t}"],
      ["{a} has the attribute {b}, which UBL 2.1 does not allow there", "{a} ha l'attributo {b}, che UBL 2.1 non ammette in quel punto"]
    ]);
  }
  window.UblSchema = { check, report, rules: RULES.map((r) => "UBL-XSD-" + r[0]) };
})();
